INSERT INTO pet_species (id, code, display_name, description, icon_res) VALUES (1, 'PERRO', 'Perro', 'Compañero leal y juguetón. Necesita paseos, ejercicio y mucha compañía.', 'ic_mod_adopcion');
INSERT INTO pet_species (id, code, display_name, description, icon_res) VALUES (2, 'GATO', 'Gato', 'Independiente y curioso. Necesita un espacio propio, arañador y rutina tranquila.', 'ic_mod_adopcion');
INSERT INTO pet_species (id, code, display_name, description, icon_res) VALUES (3, 'CONEJO', 'Conejo', 'Herbívoro sensible. Necesita heno fresco siempre disponible y un espacio seguro.', 'ic_mod_adopcion');
INSERT INTO pet_species (id, code, display_name, description, icon_res) VALUES (4, 'HAMSTER', 'Hámster', 'Pequeño roedor nocturno. Necesita una jaula enriquecida y silencio de día.', 'ic_mod_adopcion');
INSERT INTO pet_species (id, code, display_name, description, icon_res) VALUES (5, 'AVE', 'Ave doméstica', 'Inteligente y sociable. Necesita estímulos, vuelo controlado y una dieta variada.', 'ic_mod_adopcion');
INSERT INTO pet_need_definitions (id, species_id, need_type, session_decay, care_tip) VALUES (1, 1, 'ALIMENTACION', 8, 'Consejo educativo específico de PERRO para ALIMENTACION.');
