INSERT INTO home_items (id, category, name, icon_res, description, compatible_species_csv) VALUES (1, 'CUENCO_COMIDA', 'Cuenco de comida', 'item_cuenco_comida', 'Debe estar limpio y con la ración adecuada para cada especie.', 'PERRO,GATO,CONEJO,HAMSTER,AVE');
INSERT INTO home_items (id, category, name, icon_res, description, compatible_species_csv) VALUES (2, 'CUENCO_AGUA', 'Cuenco de agua fresca', 'item_cuenco_agua', 'El agua limpia debe estar siempre disponible, cerca pero no encima de la comida.', 'PERRO,GATO,CONEJO,HAMSTER,AVE');
INSERT INTO home_items (id, category, name, icon_res, description, compatible_species_csv) VALUES (3, 'CAMA', 'Cama o nido acogedor', 'item_cama', 'Un lugar suave y tranquilo donde la mascota pueda descansar sin ser molestada.', 'PERRO,GATO,CONEJO');
INSERT INTO home_items (id, category, name, icon_res, description, compatible_species_csv) VALUES (4, 'JUGUETE', 'Pelota de juego', 'item_juguete_pelota', 'Estimula el juego activo y ayuda a gastar energía de forma divertida.', 'PERRO,GATO');
INSERT INTO home_items (id, category, name, icon_res, description, compatible_species_csv) VALUES (5, 'HIGIENE', 'Cepillo de aseo', 'item_cepillo', 'Ayuda a mantener el pelaje limpio y sin nudos; también fortalece el vínculo.', 'PERRO,GATO,CONEJO');
INSERT INTO home_items (id, category, name, icon_res, description, compatible_species_csv) VALUES (6, 'ENTORNO', 'Correa para paseo', 'item_correa', 'Necesaria para pasear de forma segura fuera de casa.', 'PERRO');
INSERT INTO home_items (id, category, name, icon_res, description, compatible_species_csv) VALUES (7, 'ENTORNO', 'Planta segura de interior', 'item_planta_interior', 'Decora el espacio; siempre debe verificarse que no sea tóxica para la mascota.', 'GATO,CONEJO,AVE');
INSERT INTO home_items (id, category, name, icon_res, description, compatible_species_csv) VALUES (8, 'ENTORNO', 'Ventana con luz natural', 'item_ventana_luz', 'La luz natural regula el ritmo de sueño y actividad de la mascota.', 'PERRO,GATO,CONEJO,HAMSTER,AVE');
INSERT INTO badges (id, code, name, description, icon_res, tier) VALUES (1, 'PRIMERA_ADOPCION', 'Primera adopción', 'Adoptaste a tu primera mascota virtual.', 'badge_primera_adopcion', 1);
INSERT INTO badges (id, code, name, description, icon_res, tier) VALUES (2, 'MAESTRO_COMIDAS', 'Maestro de comidas', 'Clasificaste correctamente 15 tarjetas de alimentos.', 'badge_maestro_comidas', 1);
INSERT INTO badges (id, code, name, description, icon_res, tier) VALUES (3, 'HIGIENE_EXPERTA', 'Higiene experta', 'Realizaste 10 acciones de higiene con tu mascota.', 'badge_higiene_experta', 1);
INSERT INTO badges (id, code, name, description, icon_res, tier) VALUES (4, 'ENERGIA_ACTIVA', 'Energía activa', 'Completaste 10 actividades de juego o paseo.', 'badge_energia_activa', 1);
INSERT INTO badges (id, code, name, description, icon_res, tier) VALUES (5, 'GUARDIAN_BIENESTAR', 'Guardián del bienestar', 'Respondiste correctamente 10 escenarios de bienestar.', 'badge_guardian_bienestar', 2);
INSERT INTO badges (id, code, name, description, icon_res, tier) VALUES (6, 'PLANIFICADOR', 'Planificador experto', 'Completaste 5 planes diarios de cuidado.', 'badge_planificador', 2);
INSERT INTO badges (id, code, name, description, icon_res, tier) VALUES (7, 'ACADEMIA_ORO', 'Academia de oro', 'Terminaste todas las lecciones de la Academia de cuidado.', 'badge_academia_oro', 2);
INSERT INTO badges (id, code, name, description, icon_res, tier) VALUES (8, 'AMIGO_FIEL', 'Amigo fiel', 'Cuidaste a tu mascota durante 7 sesiones distintas.', 'badge_amigo_fiel', 2);
INSERT INTO badges (id, code, name, description, icon_res, tier) VALUES (9, 'VETERINARIO_JUNIOR', 'Veterinario junior', 'Respondiste correctamente 20 escenarios de bienestar en total.', 'badge_veterinario_junior', 3);
INSERT INTO badges (id, code, name, description, icon_res, tier) VALUES (10, 'DECORADOR', 'Decorador de hogares', 'Desbloqueaste 5 decoraciones distintas para el hogar.', 'badge_decorador', 3);
