INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (1, 1, 'Croquetas para perro', 'ALIMENTO_BUENO', 'food_pienso', 1, 'El pienso balanceado aporta todos los nutrientes que un perro adulto necesita.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (2, NULL, 'Zanahoria en trozos', 'ALIMENTO_BUENO', 'food_fruta_verdura', 1, 'La zanahoria es un snack crujiente, bajo en calorías y rico en fibra para perros y conejos.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (3, NULL, 'Pollo cocido sin hueso', 'ALIMENTO_BUENO', 'food_carne_pescado', 1, 'El pollo cocido, sin piel ni huesos, es una fuente segura de proteína para perros y gatos.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (4, 2, 'Croquetas para gato', 'ALIMENTO_BUENO', 'food_pienso', 1, 'El pienso específico para gatos contiene taurina, un nutriente esencial que ellos necesitan.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (5, 2, 'Atún en agua (poca cantidad)', 'ALIMENTO_BUENO', 'food_carne_pescado', 1, 'En cantidades pequeñas y ocasionales, el atún natural puede ser un premio para gatos.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (6, 3, 'Heno fresco', 'ALIMENTO_BUENO', 'food_fruta_verdura', 1, 'El heno debe estar siempre disponible: ayuda a la digestión y desgasta los dientes del conejo.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (7, 3, 'Hojas de lechuga romana', 'ALIMENTO_BUENO', 'food_fruta_verdura', 1, 'En pequeñas cantidades, la lechuga romana es segura y refrescante para el conejo.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (8, 4, 'Mezcla de semillas para hámster', 'ALIMENTO_BUENO', 'food_pienso', 1, 'Una mezcla equilibrada de semillas es la base de la dieta de un hámster.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (9, NULL, 'Trocito de manzana sin semillas', 'ALIMENTO_BUENO', 'food_fruta_verdura', 1, 'La manzana sin semillas es un premio ocasional seguro para hámsters y aves.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (10, 5, 'Mezcla de semillas para ave', 'ALIMENTO_BUENO', 'food_pienso', 1, 'La mezcla de semillas específica cubre las necesidades energéticas del ave.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (11, 5, 'Brócoli al vapor en trocitos', 'ALIMENTO_BUENO', 'food_fruta_verdura', 1, 'El brócoli cocido y en trozos pequeños aporta vitaminas sin dañar al ave.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (12, NULL, 'Agua fresca y limpia', 'ALIMENTO_BUENO', 'food_agua_fresca', 1, 'El agua limpia y renovada a diario es esencial para todas las especies.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (13, 3, 'Pepino en rodajas', 'ALIMENTO_BUENO', 'food_fruta_verdura', 1, 'El pepino hidrata y es un snack ligero apto para conejos y cobayas.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (14, 1, 'Calabacín cocido', 'ALIMENTO_BUENO', 'food_fruta_verdura', 1, 'El calabacín cocido en trozos pequeños es suave para el estómago del perro.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (15, NULL, 'Arándanos frescos', 'ALIMENTO_BUENO', 'food_fruta_verdura', 1, 'Los arándanos son un premio saludable y antioxidante para perros y aves.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (16, 2, 'Sardina cocida sin sal', 'ALIMENTO_BUENO', 'food_carne_pescado', 1, 'El pescado azul sin sal aporta ácidos grasos beneficiosos para el gato.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (17, 4, 'Pipas de girasol (con moderación)', 'ALIMENTO_BUENO', 'food_pienso', 1, 'En pequeñas cantidades, las pipas sin sal son un premio energético para el hámster.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (18, 3, 'Espinaca cruda en poca cantidad', 'ALIMENTO_BUENO', 'food_fruta_verdura', 1, 'Ofrecida con moderación, la espinaca aporta hierro al conejo.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (19, 1, 'Huevo cocido (poca cantidad)', 'ALIMENTO_BUENO', 'food_carne_pescado', 1, 'El huevo bien cocido, sin sal, es una fuente ocasional de proteína para el perro.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (20, NULL, 'Fresas en trozos pequeños', 'ALIMENTO_BUENO', 'food_fruta_verdura', 1, 'Las fresas son un premio dulce y natural, seguro con moderación.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (21, NULL, 'Chocolate', 'ALIMENTO_MALO', 'food_dulce_prohibido', 0, 'El chocolate contiene teobromina, una sustancia tóxica y peligrosa para perros y gatos.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (22, NULL, 'Uvas y pasas', 'ALIMENTO_MALO', 'food_fruta_verdura', 0, 'Las uvas y pasas pueden dañar gravemente los riñones de un perro, aunque parezcan inofensivas.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (23, NULL, 'Cebolla y ajo', 'ALIMENTO_MALO', 'food_planta_toxica', 0, 'La cebolla y el ajo dañan los glóbulos rojos de perros y gatos, incluso cocinados.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (24, NULL, 'Huesos de pollo cocidos', 'ALIMENTO_MALO', 'food_hueso_prohibido', 0, 'Los huesos cocidos se astillan fácilmente y pueden herir el interior del perro.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (25, NULL, 'Leche de vaca', 'ALIMENTO_MALO', 'food_lacteo', 0, 'Muchos gatos y perros adultos no digieren bien la lactosa; puede causarles malestar.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (26, 5, 'Aguacate', 'ALIMENTO_MALO', 'food_planta_toxica', 0, 'El aguacate contiene persina, una sustancia tóxica sobre todo para aves.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (27, NULL, 'Caramelos y golosinas', 'ALIMENTO_MALO', 'food_dulce_prohibido', 0, 'El azúcar y los edulcorantes artificiales pueden ser tóxicos y dañar los dientes.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (28, NULL, 'Café o bebidas con cafeína', 'ALIMENTO_MALO', 'food_dulce_prohibido', 0, 'La cafeína acelera peligrosamente el corazón de perros y gatos, incluso en pequeñas dosis.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (29, 3, 'Lechuga iceberg en exceso', 'ALIMENTO_MALO', 'food_fruta_verdura', 0, 'En exceso aporta poca fibra y puede causar diarrea en el conejo.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (30, NULL, 'Comida frita o con mucha sal', 'ALIMENTO_MALO', 'food_dulce_prohibido', 0, 'La comida grasa o salada puede dañar el estómago y el corazón de la mascota.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (31, 3, 'Ruibarbo y sus hojas', 'ALIMENTO_MALO', 'food_planta_toxica', 0, 'Las hojas de ruibarbo son tóxicas para conejos y otros pequeños mamíferos.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (32, NULL, 'Semillas de manzana', 'ALIMENTO_MALO', 'food_planta_toxica', 0, 'Las semillas de manzana contienen una sustancia tóxica; solo la pulpa es segura.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (33, 4, 'Cítricos (naranja, limón)', 'ALIMENTO_MALO', 'food_fruta_verdura', 0, 'Los cítricos pueden irritar el estómago del hámster y de las aves.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (34, 1, 'Xilitol (chicles sin azúcar)', 'ALIMENTO_MALO', 'food_dulce_prohibido', 0, 'El xilitol es un edulcorante muy tóxico incluso en cantidades mínimas para el perro.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (35, 3, 'Perejil en grandes cantidades', 'ALIMENTO_MALO', 'food_fruta_verdura', 0, 'En grandes cantidades puede afectar los riñones del conejo; solo en pequeñas porciones.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (36, NULL, 'Dejar agua estancada varios días', 'SITUACION', 'food_agua_fresca', 0, 'El agua debe cambiarse todos los días; el agua estancada acumula bacterias.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (37, NULL, 'Cambiar el agua todos los días', 'SITUACION', 'food_agua_fresca', 1, 'Renovar el agua a diario mantiene a la mascota hidratada y sana.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (38, 4, 'Bañar al hámster con agua', 'SITUACION', 'food_agua_fresca', 0, 'Los hámsters se asean solos; bañarlos con agua puede enfermarlos por el frío.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (39, 4, 'Ofrecer un baño de arena al hámster', 'SITUACION', 'food_pienso', 1, 'Un baño de arena especial permite al hámster limpiarse de forma natural y segura.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (40, 1, 'Dejar al perro sin paseo varios días', 'SITUACION', 'food_hueso_prohibido', 0, 'El perro necesita salir a pasear a diario para su salud física y mental.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (41, 1, 'Sacar a pasear al perro cada día', 'SITUACION', 'food_hueso_prohibido', 1, 'El paseo diario cubre su necesidad de actividad y de explorar el entorno.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (42, NULL, 'Limpiar la jaula solo una vez al mes', 'SITUACION', 'food_pienso', 0, 'La jaula debe limpiarse con frecuencia para evitar malos olores y enfermedades.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (43, NULL, 'Limpiar la jaula o el espacio cada semana', 'SITUACION', 'food_pienso', 1, 'Una limpieza regular mantiene el espacio de la mascota sano y cómodo.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (44, NULL, 'Dejar comida sin terminar varios días en el plato', 'SITUACION', 'food_pienso', 0, 'La comida que se echa a perder debe retirarse para que no enferme a la mascota.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (45, 3, 'Ofrecer heno fresco cada día al conejo', 'SITUACION', 'food_fruta_verdura', 1, 'Renovar el heno a diario asegura que el conejo siempre tenga fibra fresca.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (46, 5, 'Dejar al ave sin salir nunca de la jaula', 'SITUACION', 'food_pienso', 0, 'El ave necesita tiempo fuera de la jaula, en un espacio seguro, para volar y estirar las alas.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (47, 5, 'Dejar salir al ave a un espacio seguro y supervisado', 'SITUACION', 'food_pienso', 1, 'El tiempo de vuelo supervisado es clave para el bienestar físico del ave.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (48, 1, 'Cepillar al perro de pelo largo cada semana', 'SITUACION', 'food_pienso', 1, 'El cepillado regular evita nudos y ayuda a detectar heridas o parásitos a tiempo.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (49, 4, 'No cambiar nunca el sustrato del hámster', 'SITUACION', 'food_pienso', 0, 'Un sustrato sucio genera humedad y malos olores que afectan la salud del hámster.');
INSERT INTO food_items (id, species_id, name, category, icon_res, is_appropriate, explanation) VALUES (50, NULL, 'Chocolate con leche como premio', 'ALIMENTO_MALO', 'food_dulce_prohibido', 0, 'Ningún tipo de chocolate es seguro para mascotas, ni siquiera en pequeñas cantidades.');
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (1, 1, 'Tu perro se rasca mucho la oreja y la sacude todo el tiempo.', 'ic_mod_bienestar', 'Ignorarlo, seguro se le pasa solo|Revisar con cuidado y avisar a un adulto o al veterinario|Ponerle un perfume para que huela mejor', 1, 'Rascarse mucho la oreja puede indicar una infección o un objeto molestándole; conviene que un adulto lo revise.', 1);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (2, 1, 'Después de pasear, tu perro jadea mucho y busca la sombra.', 'ic_mod_bienestar', 'Dejarlo descansar y ofrecerle agua fresca|Obligarlo a seguir jugando|Darle chocolate para animarlo', 0, 'Jadear y buscar sombra es normal tras el ejercicio: necesita descanso y agua fresca.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (3, 1, 'Tu perro no ha tocado su comida en todo el día y está decaído.', 'ic_mod_bienestar', 'Esperar una semana a ver qué pasa|Registrar la situación y comentarlo con un adulto o veterinario|Cambiarle la comida por chocolate', 1, 'No comer durante un día entero junto con decaimiento merece atención de un adulto o veterinario.', 1);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (4, 1, 'Ves que tu perro mueve la cola y trae su juguete favorito.', 'ic_mod_bienestar', 'Jugar un rato con él|Ignorarlo por completo|Regañarlo sin motivo', 0, 'Traer el juguete y mover la cola son señales de que quiere jugar; responder fortalece el vínculo.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (5, 1, 'Hace mucho calor y vas a dejar a tu perro en el jardín todo el día.', 'ic_mod_bienestar', 'Dejarlo sin sombra ni agua|Asegurarte de que tenga sombra y agua fresca disponible|Ponerle un abrigo', 1, 'En días de calor, la sombra y el agua fresca son esenciales para evitar un golpe de calor.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (6, 1, 'Tu perro tiembla, se esconde y no quiere salir durante una tormenta.', 'ic_mod_bienestar', 'Forzarlo a salir igualmente|Dejarle un lugar tranquilo y acompañarlo con calma|Dejarlo solo y cerrar la puerta', 1, 'El miedo a los truenos es común; ofrecer calma y un refugio tranquilo ayuda a que se sienta seguro.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (7, 2, 'Tu gato se esconde debajo de la cama y no quiere salir en todo el día.', 'ic_mod_bienestar', 'Sacarlo a la fuerza|Dejarle espacio y observar si vuelve a comer y jugar con normalidad|Ignorarlo una semana entera', 1, 'Esconderse un rato es normal en gatos, pero si persiste conviene observarlo y, si sigue, avisar a un adulto.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (8, 2, 'Notas que tu gato vomita una bola de pelo de vez en cuando.', 'ic_mod_bienestar', 'Es normal ocasionalmente; puedes cepillarlo más seguido|Alarmarse y dejar de alimentarlo|Bañarlo inmediatamente', 0, 'Las bolas de pelo ocasionales son comunes; cepillarlo con más frecuencia reduce su formación.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (9, 2, 'Tu gato araña el sofá en vez del rascador.', 'ic_mod_bienestar', 'Regañarlo fuerte y encerrarlo|Colocar el rascador cerca del sofá y premiarlo cuando lo use|Quitarle todas las uñas', 1, 'Redirigir el comportamiento hacia el rascador con paciencia y premios funciona mejor que el castigo.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (10, 2, 'Tu gato maúlla mucho y no se acerca al plato de agua.', 'ic_mod_bienestar', 'Cambiar el agua de lugar, lejos de la comida, y ofrecer agua fresca|No hacer nada|Darle solo leche de vaca', 0, 'Muchos gatos prefieren el agua lejos de la comida; renovarla puede animarlo a beber más.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (11, 2, 'Tu gato deja de usar la caja de arena y hace sus necesidades fuera.', 'ic_mod_bienestar', 'Castigarlo|Revisar que la arena esté limpia y, si continúa, avisar a un adulto|Cambiarlo de casa', 1, 'Este cambio de conducta puede indicar estrés o un problema de salud; conviene revisarlo con un adulto.', 1);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (12, 2, 'Ves que tu gato duerme casi todo el día.', 'ic_mod_bienestar', 'Preocuparte, es raro que duerma tanto|Es normal: los gatos duermen muchas horas al día|Despertarlo cada hora', 1, 'Dormir gran parte del día es completamente normal en la conducta felina.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (13, 3, 'Notas que tu conejo no ha comido heno en todo el día.', 'ic_mod_bienestar', 'Esperar sin hacer nada|Avisar a un adulto: en conejos, dejar de comer es una señal urgente|Darle solo golosinas dulces', 1, 'En conejos, dejar de comer incluso pocas horas puede ser grave y requiere atención rápida de un adulto.', 1);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (14, 3, 'Tu conejo golpea el suelo con la pata trasera de repente.', 'ic_mod_bienestar', 'Ignorarlo|Revisar el entorno: puede estar advirtiendo de algo que le asusta|Regañarlo', 1, 'Golpear el suelo es una señal de alerta o alarma; conviene revisar si algo lo está asustando.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (15, 3, 'Ves que tu conejo se estira relajado y mordisquea despacio el heno.', 'ic_mod_bienestar', 'Dejarlo tranquilo, está cómodo y relajado|Molestarlo para que se mueva|Sacarlo de su espacio a la fuerza', 0, 'Un conejo relajado que come con calma está mostrando bienestar; lo mejor es no interrumpirlo.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (16, 3, 'Su jaula lleva dos semanas sin limpiarse y huele fuerte.', 'ic_mod_bienestar', 'Dejarla así, no pasa nada|Limpiarla esta misma semana con ayuda de un adulto|Rociar perfume para tapar el olor', 1, 'Un espacio limpio y seco es esencial para evitar enfermedades respiratorias y de piel.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (17, 3, 'Tu conejo se deja acariciar la cabeza pero se aparta si tocas su lomo.', 'ic_mod_bienestar', 'Respetar su límite y acariciar solo donde está cómodo|Forzarlo a que se deje tocar en todas partes|Dejar de acariciarlo para siempre', 0, 'Respetar las zonas donde el conejo se siente cómodo construye confianza poco a poco.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (18, 3, 'Hace mucho calor y el conejo está tumbado sin moverse, respirando rápido.', 'ic_mod_bienestar', 'Dejarlo al sol para que se caliente más|Llevarlo a la sombra, ofrecer agua fresca y avisar a un adulto|No hacer nada', 1, 'Los conejos son muy sensibles al calor; respirar rápido y estar inmóvil puede indicar un golpe de calor.', 1);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (19, 4, 'Tu hámster está muy quieto durante el día y no se mueve.', 'ic_mod_bienestar', 'Despertarlo para jugar|Dejarlo dormir: es un animal nocturno y de día suele descansar|Sacarlo de la jaula y sacudirlo', 1, 'Los hámsters son nocturnos; estar quietos de día es su comportamiento normal, no una señal de alarma.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (20, 4, 'Ves que tu hámster guarda comida en las mejillas y la esconde en un rincón.', 'ic_mod_bienestar', 'Es un comportamiento normal de acumulación, no hace falta hacer nada especial|Regañarlo por no comer|Quitarle toda la comida guardada', 0, 'Guardar comida en los carrillos y acumularla es un comportamiento natural del hámster.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (21, 4, 'La rueda de ejercicio de tu hámster hace un ruido chirriante constante.', 'ic_mod_bienestar', 'Ignorarlo, no afecta al hámster|Revisarla y limpiarla o engrasarla con ayuda de un adulto|Quitarle la rueda para siempre', 1, 'Una rueda que chirría puede indicar que necesita mantenimiento; además el ruido puede estresarlo.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (22, 4, 'Notas que tu hámster ha perdido pelo en una zona y se rasca mucho ahí.', 'ic_mod_bienestar', 'No darle importancia|Comentarlo con un adulto para que revise si necesita veterinario|Cortarle el pelo restante', 1, 'La pérdida de pelo localizada junto con rascado puede indicar un problema de piel a revisar.', 1);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (23, 4, 'Vas a manipular a tu hámster por primera vez en el día.', 'ic_mod_bienestar', 'Agarrarlo rápido y por la cola|Dejar que huela tu mano primero y luego tomarlo con ambas manos, con calma|Levantarlo de golpe mientras duerme', 1, 'Acercarse con calma y dejar que reconozca tu mano evita sustos y mordiscos.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (24, 4, 'El bebedero de tu hámster está vacío desde ayer.', 'ic_mod_bienestar', 'Rellenarlo cuanto antes con agua limpia|Esperar al día siguiente|Darle solo fruta en su lugar', 0, 'El agua no debe faltar nunca; hay que rellenarla en cuanto se detecta que está vacía.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (25, 5, 'Tu ave se arranca plumas del pecho repetidamente.', 'ic_mod_bienestar', 'Ignorarlo, las plumas vuelven a crecer solas siempre|Comentarlo con un adulto: puede ser estrés o aburrimiento|Cubrir la jaula todo el día', 1, 'Arrancarse plumas suele indicar estrés, aburrimiento o un problema de salud; conviene consultarlo.', 1);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (26, 5, 'Ves que tu ave canta y salta activamente en su percha por la mañana.', 'ic_mod_bienestar', 'Es una señal de que está contenta y en buen estado|Es preocupante y hay que llevarla al veterinario ya|Hay que hacerla callar', 0, 'Cantar y moverse con energía por la mañana es una señal típica de bienestar en muchas aves.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (27, 5, 'Tu ave está erizada, con los ojos entrecerrados y no come.', 'ic_mod_bienestar', 'Esperar unos días a ver si mejora sola|Avisar a un adulto pronto: puede ser un signo de enfermedad|Darle solo agua con azúcar', 1, 'Un ave enferma suele esconder los síntomas; estar erizada y sin comer es señal de alarma que requiere atención pronto.', 1);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (28, 5, 'Vas a limpiar el bebedero y el comedero del ave.', 'ic_mod_bienestar', 'Lavarlos con agua y dejar todo limpio y seco antes de rellenar|Rellenar directamente sin lavar|Usar detergente fuerte sin enjuagar', 0, 'Lavar bien los recipientes evita bacterias y mantiene la comida y el agua en buen estado.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (29, 5, 'El ave lleva todo el día en la jaula sin salir a volar.', 'ic_mod_bienestar', 'Está bien así siempre|Ofrecerle un rato de vuelo supervisado en un espacio seguro|Dejarla encerrada una semana más', 1, 'El tiempo de vuelo supervisado es importante para su salud física y mental.', 0);
INSERT INTO wellbeing_scenarios (id, species_id, situation_text, icon_res, options_csv, correct_option_index, explanation, recommend_ask_adult) VALUES (30, 5, 'Notas que el ave se acerca a los barrotes cuando te ve llegar.', 'ic_mod_bienestar', 'Ignorarla y alejarte|Saludarla con calma y ofrecerle un momento de atención|Golpear la jaula para jugar', 1, 'Acercarse a saludar es una señal de vínculo positivo; responder con calma refuerza esa confianza.', 0);
